"""Reviewed PDF transcription. Run this script to regenerate adjacent catalog.json.

Stable slugs are permanent identities. Empty fields mean not stated, not inferred.
Each pipe-delimited row retains its own source page and row number.
"""
from pathlib import Path
import json,re

records={}
def add(source, category, text):
    for line in text.strip().splitlines():
        if not line.strip(): continue
        parts=line.split('|')
        assert len(parts)==12,(len(parts),line)
        slug,ref,name,gov,area,address,phones,needs,stages,classes,capacity,ages=parts
        page,row=ref.split(':')
        key='kw-'+slug
        item=records.setdefault(key,dict(id=key,nameAr=name,categories=[],observations=[],reviewStatus='unverified'))
        if category not in item['categories']: item['categories'].append(category)
        item['observations'].append(dict(sourceId=source,page=int(page),row=row,nameAr=name,governorateAr=gov or None,areaAr=area or None,addressAr=address or None,phones=phones.split(',') if phones else [],needsAr=needs or None,stagesAr=stages or None,classroomAr=classes or None,capacityAr=capacity or None,agesAr=ages or None))

