for slug,note in notes.items(): records['kw-'+slug]['reviewNotesAr']=[note]
for slug,fields in extra.items(): records['kw-'+slug]['sourceExtras']=fields
for item in records.values():
    item.setdefault('reviewNotesAr',[])
    # Stable tags are a search aid, never a broader eligibility claim. Raw wording remains visible.
    needs=' '.join(o['needsAr'] or '' for o in item['observations'])
    tags=[]
    for tag,pattern in [('autism','توحد'),('intellectual','ذهن|عقلي'),('hearing','سمع'),('vision','بصر'),('motor','حرك|جسدي'),('down','داون'),('learning','صعوبات|بطء|تعليمي'),('developmental','تطور|نمائي'),('speech','نطق|لغوي'),('multiple','مزدوج'),('cerebral-palsy','شلل'),('adhd','فرط|تشتت'),('epilepsy','صرع')]:
        if re.search(pattern,needs): tags.append(tag)
    if 'ماعدا الإعاقة البصرية' in needs:
        tags=[t for t in tags if t!='vision']
    if 'جميع الإعاقات' in needs: tags.append('all-as-reported')
    item['disabilityTags']=tags
    stages=' '.join(o['stagesAr'] or '' for o in item['observations'])
    item['stageTags']=['nursery'] if 'nursery' in item['categories'] else []
    for tag,pattern in [('kindergarten','روضة|رياض'),('primary','ابتدائي|الخامس|الأول'),('middle','متوسط|الثامن'),('secondary','ثانوي|الثاني عشر|الثانوية')]:
        if re.search(pattern,stages): item['stageTags'].append(tag)
    if 'جميع المراحل' in stages: item['stageTags'].append('all-as-reported')
    item['disabilityTags']=list(dict.fromkeys(item['disabilityTags']))
    # Never assign verified English names or map coordinates from transliteration/geocoding.
    item['nameEn']=None
    item['verifiedMapUrl']=None

