review=['# Institution source inventory', '',
    'Generated from the reviewed transcription in `build_catalog.py`. All 90 institutions require current-operation and contact verification. Source observations are retained separately in `catalog.json`; none is an admission or availability claim.', '',
    'The three files contain two unique documents (16 unique pages). `menwhm.pdf` and `menwhmة.pdf` are byte-identical. The other document is dated 20 April 2023. There are 164 source observations after consolidating repeated institution identities.', '',
    'There are 40 school listings, 39 nursery listings and 12 rehabilitation listings. The Kuwait Autism Center appears in two categories under one ID, so these category counts sum to 91.', '',
    '## Added source institutions', '']
for kind,title in [('school','Schools — المدارس'),('nursery','Nurseries — الحضانات'),('rehabilitation','Rehabilitation Centers — مراكز التأهيل')]:
    review.extend(['### '+title,''])
    for item in records.values():
        if kind in item['categories']:
            refs='; '.join(f"{o['sourceId']} p{o['page']} row {o['row']}" for o in item['observations'])
            review.append(f"- **{item['nameAr']}** (`{item['id']}`): {refs}")
    review.append('')
review.extend(['## Specific review notes', '',
    'These are notable conflicts, duplicate decisions, shared capacities or classification ambiguities. Other differences in source wording remain visible in the app. Missing values remain unknown; no English institution names or map locations have been verified.', ''])
for item in records.values():
    for note in item['reviewNotesAr']:
        review.append(f"- **{item['nameAr']}** (`{item['id']}`): {note}")
dest.with_name('REVIEW.md').write_text('\n'.join(review)+'\n',encoding='utf-8')

